package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import org.springframework.stereotype.Service;

/** The figure a claim shows and totals: the due fixed when it was settled, else the figure its
 *  person's last statement bound it to, else live at its person's grade's rate in force on the
 *  claim's date, at least the sheet's floor (null, n/a, when there is no rate). */
@Service
public class Figures {

    private final Rates rates;
    private final Settings settings;

    public Figures(Rates rates, Settings settings) {
        this.rates = rates;
        this.settings = settings;
    }

    public BigDecimal figure(Claim claim, String grade) {
        if (claim.getDue() != null) return claim.getDue();
        if (claim.isStated()) return claim.getStatedDue();
        return live(claim, grade);
    }

    /** The claim's due at its person's grade's rate in force on the claim's date: amount times the
     *  rate divided by 100, rounded half to even to two decimals, raised to the sheet's floor when it
     *  is below it; null when there is no rate. */
    public BigDecimal live(Claim claim, String grade) {
        BigDecimal pct = rates.pct(claim.getSheetId(), grade, claim.getDate());
        if (pct == null) return null;
        BigDecimal due = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100)).setScale(2, RoundingMode.HALF_EVEN);
        return due.max(settings.floor(claim.getSheetId()));
    }
}
package net.officefloor.hq.app.claim;

/** A claim as the screen sees it: the amount with two decimals, the date as yyyy-mm-dd,
 *  the status as DRAFT, OPEN, SETTLED or VOID, the number null when the claim has none, the due
 *  fixed at settling with two decimals, null when it has none (its due is worked out live),
 *  who opened it, null while it has not been opened, whether its person's last statement binds it
 *  and the figure it binds it to (two decimals; null when unbound or bound to n/a). */
public record ClaimResponse(long id, long personId, String amount, String date, String note,
        String status, Long number, String due, String openedBy, boolean stated, String statedDue) {
    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getDue() != null ? claim.getDue().toPlainString() : null, claim.getOpenedBy(),
                claim.isStated(), claim.getStatedDue() != null ? claim.getStatedDue().toPlainString() : null);
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithClaims {
    public void respond(@PathVariable("sheetId") String sheetId, Claims claims,
            ObjectResponse<List<ClaimResponse>> response) {
        response.send(claims.onSheet(sheetId).stream().map(ClaimResponse::from).toList());
    }
}
package net.officefloor.hq.app.person;

/** A person as the screen sees it, with their statement count, and the last statement's due-total
 *  (two decimals, null when it was n/a or none was taken) and date (yyyy-mm-dd, null when none was),
 *  and whether they are retired and from when (yyyy-mm-dd, null when not retired),
 *  and whether they are on hold. */
public record PersonResponse(long id, String name, String grade, int version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held) {
    public static PersonResponse from(Person person) {
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(), person.getVersion(),
                person.getStatementCount(),
                person.getStatedTotal() != null ? person.getStatedTotal().toPlainString() : null,
                person.getStatementDate() != null ? person.getStatementDate().toString() : null,
                person.isRetired(), person.getRetiredFrom() != null ? person.getRetiredFrom().toString() : null,
                person.isHeld());
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithPeople {
    public void respond(@PathVariable("sheetId") String sheetId, People people,
            ObjectResponse<List<PersonResponse>> response) {
        response.send(people.onSheet(sheetId).stream().map(PersonResponse::from).toList());
    }
}
package net.officefloor.hq.app.sheet;

/** A sheet as the screen sees it; `today` is ISO yyyy-MM-dd. */
public record SheetResponse(String id, String today) {
}
package net.officefloor.hq.app.sheet;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithSheet {
    public void respond(@PathVariable("sheetId") String sheetId, Sheets sheets,
            ObjectResponse<SheetResponse> response) {
        response.send(new SheetResponse(sheetId, sheets.today(sheetId).toString()));
    }
}
